/*
===============================================================================
DEFINICIÓN CANÓNICA VERSIONADA
Procedimiento: integracion_datos_analitica.usp_cargar_evolucion_cartera_claro

Origen:
- definición validada en producción el 18/09/2026;
- corrección CLARO EVOLUTION transitoria V2;
- conserva las guardas históricas existentes;
- no habilita el modo histórico de Gobierno para Administrativo.

No editar una migración histórica para desplegar este cambio. Esta definición
representa el estado canónico que debe quedar instalado.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [integracion_datos_analitica].[usp_cargar_evolucion_cartera_claro]      @id_cliente_crm   INT,      @anio_campana   SMALLINT,      @mes_campana  TINYINT,      @codigo_unidad_negocio VARCHAR(20) = 'ADMINISTRATIVO',
      @historico_limitar_gestionados_a_asignados BIT = 0,
      @normalizar_desfase_transitorio BIT = 0
  AS  BEGIN      SET NOCOUNT ON;      SET XACT_ABORT ON;          /* ============================================================         0. VALIDACIONES         ============================================================ */        IF @id_cliente_crm IS NULL OR @id_cliente_crm <= 0          THROW 51500, '@id_cliente_crm es obligatorio.', 1;        IF @anio_campana IS NULL OR @anio_campana < 2000          THROW 51501, '@anio_campana no es válido.', 1;        IF @mes_campana NOT BETWEEN 1 AND 12          THROW 51502, '@mes_campana debe estar entre 1 y 12.', 1;          SET @codigo_unidad_negocio = UPPER(LTRIM(RTRIM(ISNULL(@codigo_unidad_negocio, ''))));          IF @codigo_unidad_negocio NOT IN ('ADMINISTRATIVO', 'GOBIERNO')          THROW 51511, '@codigo_unidad_negocio debe ser ADMINISTRATIVO o GOBIERNO.', 1;          SET @historico_limitar_gestionados_a_asignados =
          ISNULL(@historico_limitar_gestionados_a_asignados, 0);

      SET @normalizar_desfase_transitorio =
          ISNULL(@normalizar_desfase_transitorio, 0);          DECLARE @business_unit_name VARCHAR(150) =              CASE @codigo_unidad_negocio                  WHEN 'ADMINISTRATIVO' THEN 'CLARO ADMINISTRATIVO'                  WHEN 'GOBIERNO' THEN 'CLARO GOBIERNO'              END;          DECLARE @watermark_source_code VARCHAR(100) =              CASE @codigo_unidad_negocio                  WHEN 'ADMINISTRATIVO' THEN 'CLARO_EVOLUTION_DAILY'                  WHEN 'GOBIERNO' THEN 'CLARO_GOB_EVOLUTION_DAILY'              END;          /* ============================================================         1. CAMPAÑA         ============================================================ */        DECLARE @campaign_start DATE =          DATEFROMPARTS(@anio_campana, @mes_campana, 1);        DECLARE @campaign_end DATE =          EOMONTH(@campaign_start);        IF @historico_limitar_gestionados_a_asignados = 1
         AND @codigo_unidad_negocio <> 'GOBIERNO'
          THROW 51512,
              '@historico_limitar_gestionados_a_asignados solo está permitido para GOBIERNO.',
              1;

      IF @historico_limitar_gestionados_a_asignados = 1
         AND @campaign_end >= CONVERT(DATE, SYSDATETIME())
          THROW 51513,
              '@historico_limitar_gestionados_a_asignados solo está permitido para campañas cerradas.',
              1;

      /*
        Modo operacional D-1:
        - NO reutiliza la excepción histórica de Gobierno;
        - se permite para ADMINISTRATIVO y GOBIERNO;
        - solo puede activarse para la campaña que contiene AYER.
        Las guardas 51514/51515 siguen siendo obligatorias más abajo.
      */
      IF @normalizar_desfase_transitorio = 1
         AND DATEADD(DAY, -1, CONVERT(DATE, SYSDATETIME()))
             NOT BETWEEN @campaign_start AND @campaign_end
          THROW 51516,
              '@normalizar_desfase_transitorio solo está permitido para la campaña operacional D-1.',
              1;        DECLARE @source_campaign_code VARCHAR(15) =          CONCAT(              'C-',              RIGHT(CONCAT('0', @mes_campana), 2)          );        DECLARE @codigo_campana VARCHAR(20) =          CONCAT(              @anio_campana,              '-',              RIGHT(CONCAT('0', @mes_campana), 2)          );          DECLARE @client_key INT;      DECLARE @campaign_key INT;        DECLARE @source_rows BIGINT;      DECLARE @source_as_of_at DATETIME2(3);        DECLARE @invalid_date_rows BIGINT;      DECLARE @duplicate_grain_rows BIGINT;      DECLARE @unmapped_portfolio_rows BIGINT;      DECLARE @invalid_balance_rows BIGINT;      DECLARE @negative_balance_rows BIGINT;      DECLARE @managed_over_assigned_rows BIGINT;      DECLARE @assigned_decrease_rows BIGINT;      DECLARE @final_incompatible_portfolios BIGINT;      DECLARE @max_managed_over_assigned BIGINT;          SELECT          @client_key = c.clave_cliente      FROM analitica.dim_cliente AS c      WHERE c.id_cliente_crm = @id_cliente_crm;          IF @client_key IS NULL          THROW 51503,              'El cliente no existe en analitica.dim_cliente.',              1;          SELECT          @campaign_key = c.clave_campana      FROM analitica.dim_campana AS c      WHERE c.clave_cliente = @client_key        AND c.codigo_campana = @codigo_campana;          IF @campaign_key IS NULL          THROW 51504,              'La campaña no existe en analitica.dim_campana. Ejecute primero el ETL snapshot.',              1;          /* ============================================================         2. FILAS FÍSICAS EVOL DEL MES REAL           IMPORTANTE:         CampAval identifica la campaña fuente, pero no garantiza         que todas las filas tengan una fecha perteneciente al mes.           Por eso el dataset canonical diario queda acotado además por:               fecha >= campaign_start             fecha <= campaign_end           Ejemplo julio:             nid_cartera 34364             CampAval = C-07             fechas = 2026-08-01 .. 2026-08-18           Esas filas NO pertenecen al histórico diario de julio.         ============================================================ */        SELECT          @source_rows = COUNT_BIG(*),            @source_as_of_at =              MAX(CONVERT(DATETIME2(3), s.fecha))        FROM integracion_datos_analitica.v_origen_evolucion_cartera_claro AS s        WHERE s.codigo_unidad_negocio = @codigo_unidad_negocio        AND s.AñoAval = @anio_campana        AND s.CampAval = @source_campaign_code          AND s.fecha >= @campaign_start        AND s.fecha <= @campaign_end;          IF ISNULL(@source_rows, 0) = 0          THROW 51505,              'EVOL no tiene filas dentro del mes de campaña solicitado.',              1;          /* ============================================================         3. FECHAS NULL CON PAYLOAD           Las fechas posteriores/anteriores al mes se excluyen por         diseño del ETL mensual.           Pero una fila con fecha NULL y datos reales sí constituye         una inconsistencia porque no sabemos a qué día asignarla.         ============================================================ */        SELECT          @invalid_date_rows = COUNT_BIG(*)        FROM integracion_datos_analitica.v_origen_evolucion_cartera_claro AS s        WHERE s.codigo_unidad_negocio = @codigo_unidad_negocio        AND s.AñoAval = @anio_campana        AND s.CampAval = @source_campaign_code          AND s.fecha IS NULL          AND        (               s.TOTAL_CLIENTES IS NOT NULL            OR s.ASIGNACION IS NOT NULL              OR s.CLIENTES_GESTIONADOS IS NOT NULL            OR s.MONTO_CLIENTES_GESTIONADOS IS NOT NULL              OR s.CLIENTES_GESTIONADOS_CALL IS NOT NULL            OR s.MONTO_CLIENTES_GESTIONADOS_CALL IS NOT NULL              OR s.CLIENTES_CON_PAGOS IS NOT NULL            OR s.MONTO_DE_PAGOS IS NOT NULL              OR s.CLIENTES_CON_PROMESA IS NOT NULL            OR s.MONTO_EN_PROMESAS IS NOT NULL              OR s.CLIENTES_CON_CONTACTO_DIRECTO IS NOT NULL            OR s.MONTO_EN_CONTACTO_DIRECTO IS NOT NULL              OR s.CLIENTE_GESTIONADO_NVO IS NOT NULL            OR s.CLIENTE_GESTIONADO_CALL_NVO IS NOT NULL            OR s.CLIENTE_CON_CONTACTO_DIRECTO_NVO IS NOT NULL            OR s.CLIENTE_CON_PROMESA_NVO IS NOT NULL              OR s.ASIGNACION_FINAL IS NOT NULL            OR s.ASIGNACIoN_CARTERA_NV2_FINAL IS NOT NULL        );          IF ISNULL(@invalid_date_rows, 0) > 0          THROW 51506,              'EVOL contiene filas con fecha NULL y payload analítico.',              1;          /* ============================================================         4. CARTERAS CON PAYLOAD ANALÍTICO REAL DENTRO DEL MES           La evaluación es por cartera + mes.           0    = dato válido         NULL = ausencia de dato           Una cartera se excluye únicamente cuando TODAS sus filas         dentro del mes están completamente vacías.           Esto mantiene la corrección aplicada para junio.         ============================================================ */        IF OBJECT_ID('tempdb..#MeaningfulEvolPortfolios') IS NOT NULL          DROP TABLE #MeaningfulEvolPortfolios;          SELECT          s.nid_cartera        INTO #MeaningfulEvolPortfolios        FROM integracion_datos_analitica.v_origen_evolucion_cartera_claro AS s        WHERE s.codigo_unidad_negocio = @codigo_unidad_negocio        AND s.AñoAval = @anio_campana        AND s.CampAval = @source_campaign_code          AND s.fecha >= @campaign_start        AND s.fecha <= @campaign_end        GROUP BY          s.nid_cartera        HAVING          MAX          (              CASE                  WHEN                         s.TOTAL_CLIENTES IS NOT NULL                        OR s.ASIGNACION IS NOT NULL                        OR s.CLIENTES_GESTIONADOS IS NOT NULL                      OR s.MONTO_CLIENTES_GESTIONADOS IS NOT NULL                        OR s.CLIENTES_GESTIONADOS_CALL IS NOT NULL                      OR s.MONTO_CLIENTES_GESTIONADOS_CALL IS NOT NULL                        OR s.CLIENTES_CON_PAGOS IS NOT NULL                      OR s.MONTO_DE_PAGOS IS NOT NULL                        OR s.CLIENTES_CON_PROMESA IS NOT NULL                      OR s.MONTO_EN_PROMESAS IS NOT NULL                        OR s.CLIENTES_CON_CONTACTO_DIRECTO IS NOT NULL                      OR s.MONTO_EN_CONTACTO_DIRECTO IS NOT NULL                        OR s.CANTIDAD_DISC IS NOT NULL                      OR s.CANTIDAD_IVR IS NOT NULL                      OR s.CANTIDAD_EMAIL IS NOT NULL                      OR s.CANTIDAD_SMS IS NOT NULL                      OR s.CANTIDAD_BOT IS NOT NULL                      OR s.CANTIDAD_WHATSAPP IS NOT NULL                        OR s.CLIENTE_GESTIONADO_NVO IS NOT NULL                      OR s.CLIENTE_GESTIONADO_CALL_NVO IS NOT NULL                      OR s.CLIENTE_CON_CONTACTO_DIRECTO_NVO IS NOT NULL                      OR s.CLIENTE_CON_PROMESA_NVO IS NOT NULL                        OR s.ASIGNACION_FINAL IS NOT NULL                      OR s.ASIGNACIoN_CARTERA_NV2_FINAL IS NOT NULL                    THEN 1                  ELSE 0              END          ) = 1;          IF NOT EXISTS      (          SELECT 1          FROM #MeaningfulEvolPortfolios      )          THROW 51510,              'EVOL no contiene carteras con payload analítico dentro del mes solicitado.',              1;          /* ============================================================         5. VALIDAR GRAIN FECHA + CARTERA           Solo:             - dentro del mes             - carteras con payload real         ============================================================ */        SELECT          @duplicate_grain_rows = COUNT_BIG(*)        FROM      (          SELECT              s.fecha,              s.nid_cartera            FROM integracion_datos_analitica.v_origen_evolucion_cartera_claro AS s            INNER JOIN #MeaningfulEvolPortfolios AS ep              ON ep.nid_cartera = s.nid_cartera            WHERE s.codigo_unidad_negocio = @codigo_unidad_negocio        AND s.AñoAval = @anio_campana            AND s.CampAval = @source_campaign_code              AND s.fecha >= @campaign_start            AND s.fecha <= @campaign_end            GROUP BY              s.fecha,              s.nid_cartera            HAVING COUNT_BIG(*) <> 1        ) AS q;          IF ISNULL(@duplicate_grain_rows, 0) > 0          THROW 51507,              'EVOL no respeta el grain fecha + nid_cartera dentro del mes.',              1;          /* ============================================================         6. VALIDAR SCOPE CANONICAL           Solo las carteras con información real DENTRO DEL MES         deben existir en dim_portfolio.           Una cartera que solo tiene datos fuera del mes no forma         parte del scope mensual solicitado.           Si aparece una cartera no mapeada con datos reales dentro         de julio, 51508 seguirá deteniendo el integracion_datos_analitica.         ============================================================ */        SELECT          @unmapped_portfolio_rows = COUNT_BIG(*)        FROM #MeaningfulEvolPortfolios AS ep        LEFT JOIN analitica.dim_cartera AS p          ON p.clave_cliente = @client_key         AND p.id_cartera_origen = ep.nid_cartera         AND p.unidad_negocio_origen = @business_unit_name        WHERE p.clave_cartera IS NULL;          IF ISNULL(@unmapped_portfolio_rows, 0) > 0          THROW 51508,              'EVOL contiene carteras con datos dentro del mes fuera del scope snapshot canonical.',              1;          /* ============================================================         7. VALIDAR BALANCE / NORMALIZACION HISTORICA CONTROLADA           Semantica base:         managed_raw = acumulado MTD de CLIENTE_GESTIONADO_NVO.           Modo estricto (default = 0):         conserva el contrato previo y 51509 si managed_raw > assigned.           Modo historico Gobierno (flag = 1):         se admite SOLO el desfase transitorio managed_raw > assigned         cuando:           - la campaña está cerrada;           - TOTAL_CLIENTES no disminuye dentro de la cartera;           - al cierre del mes managed_raw <= assigned.           En esas filas se persiste:         clientes_gestionados = MIN(managed_raw, clientes_asignados)         clientes_pendientes = clientes_asignados - clientes_gestionados           No se usa CLIENTES_GESTIONADOS como reemplazo porque B1.6I         demostró que es parcial y también puede superar assigned.         ============================================================ */        IF OBJECT_ID('tempdb..#ManagedNormalized') IS NOT NULL          DROP TABLE #ManagedNormalized;        ;WITH ManagedBase AS      (          SELECT              s.fecha,              s.nid_cartera,                CONVERT(                  INT,                  ISNULL(s.TOTAL_CLIENTES, 0)              ) AS clientes_asignados,                CONVERT(                  INT,                  ISNULL(s.CLIENTE_GESTIONADO_NVO, 0)              ) AS nuevos_clientes_gestionados_dia,                SUM              (                  CONVERT(                      BIGINT,                      ISNULL(s.CLIENTE_GESTIONADO_NVO, 0)                  )              )              OVER              (                  PARTITION BY s.nid_cartera                    ORDER BY s.fecha                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW              ) AS managed_clients_raw            FROM integracion_datos_analitica.v_origen_evolucion_cartera_claro AS s            INNER JOIN #MeaningfulEvolPortfolios AS ep              ON ep.nid_cartera = s.nid_cartera            WHERE s.codigo_unidad_negocio = @codigo_unidad_negocio              AND s.AñoAval = @anio_campana              AND s.CampAval = @source_campaign_code              AND s.fecha >= @campaign_start              AND s.fecha <= @campaign_end      )      SELECT          b.fecha,          b.nid_cartera,          b.clientes_asignados,          b.nuevos_clientes_gestionados_dia,          b.managed_clients_raw        INTO #ManagedNormalized      FROM ManagedBase AS b;        SELECT          @negative_balance_rows = COUNT_BIG(*)      FROM #ManagedNormalized AS s      WHERE s.clientes_asignados < 0         OR s.nuevos_clientes_gestionados_dia < 0         OR s.managed_clients_raw < 0;        IF ISNULL(@negative_balance_rows, 0) > 0          THROW 51509,              'EVOL contiene assigned o acumulado CLIENTE_GESTIONADO_NVO negativos.',              1;        SELECT          @managed_over_assigned_rows = COUNT_BIG(*),          @max_managed_over_assigned = MAX(              CASE                  WHEN s.managed_clients_raw > s.clientes_asignados                      THEN s.managed_clients_raw - s.clientes_asignados                  ELSE 0              END          )      FROM #ManagedNormalized AS s      WHERE s.managed_clients_raw > s.clientes_asignados;        SET @invalid_balance_rows = ISNULL(@managed_over_assigned_rows, 0);        IF ISNULL(@managed_over_assigned_rows, 0) > 0
         AND @historico_limitar_gestionados_a_asignados = 0
         AND @normalizar_desfase_transitorio = 0
          THROW 51509,
              'EVOL contiene assigned o acumulado CLIENTE_GESTIONADO_NVO incompatibles.',
              1;

      IF @historico_limitar_gestionados_a_asignados = 1
         OR @normalizar_desfase_transitorio = 1
      BEGIN          ;WITH AssignedLag AS          (              SELECT                  s.nid_cartera,                  s.fecha,                  s.clientes_asignados,                  LAG(s.clientes_asignados) OVER                  (                      PARTITION BY s.nid_cartera                      ORDER BY s.fecha                  ) AS previous_assigned              FROM #ManagedNormalized AS s          )          SELECT              @assigned_decrease_rows = COUNT_BIG(*)          FROM AssignedLag          WHERE previous_assigned IS NOT NULL            AND clientes_asignados < previous_assigned;            IF ISNULL(@assigned_decrease_rows, 0) > 0              THROW 51514,                  'Normalización controlada rechazada: TOTAL_CLIENTES disminuye dentro del mes.',                  1;            ;WITH ClosingState AS          (              SELECT                  s.nid_cartera,                  s.clientes_asignados,                  s.managed_clients_raw,                  ROW_NUMBER() OVER                  (                      PARTITION BY s.nid_cartera                      ORDER BY s.fecha DESC                  ) AS rn              FROM #ManagedNormalized AS s          )          SELECT              @final_incompatible_portfolios = COUNT_BIG(*)          FROM ClosingState          WHERE rn = 1            AND managed_clients_raw > clientes_asignados;            IF ISNULL(@final_incompatible_portfolios, 0) > 0              THROW 51515,                  'Normalización controlada rechazada: el acumulado gestionado sigue superando assigned en el último estado disponible.',                  1;            IF ISNULL(@managed_over_assigned_rows, 0) > 0              PRINT CONCAT(                  CASE
                      WHEN @normalizar_desfase_transitorio = 1
                          THEN 'CLARO Evolution transient cap: '
                      ELSE 'CLARO Evolution historical cap: '
                  END,                  @managed_over_assigned_rows,                  ' filas ajustadas; máximo exceso=',                  ISNULL(@max_managed_over_assigned, 0),                  ' para ',                  @codigo_campana,                  ' / ',                  @codigo_unidad_negocio,                  '.'              );      END;          /* ============================================================         8. CARGA         ============================================================ */        BEGIN TRY            BEGIN TRANSACTION;              /* --------------------------------------------------------             8.1 Dimensión fecha             -------------------------------------------------------- */            EXEC integracion_datos_analitica.usp_asegurar_rango_fechas              @fecha_desde = @campaign_start,              @fecha_hasta = @campaign_end;              /* --------------------------------------------------------             8.2 Normalización             -------------------------------------------------------- */            IF OBJECT_ID('tempdb..#EvolutionSource') IS NOT NULL              DROP TABLE #EvolutionSource;              SELECT              CONVERT(                  INT,                  CONVERT(CHAR(8), s.fecha, 112)              ) AS clave_fecha,                p.clave_cartera,                s.clientes_asignados,                CONVERT(                  INT,                  CASE                      WHEN
                        (
                            @historico_limitar_gestionados_a_asignados = 1
                            OR @normalizar_desfase_transitorio = 1
                        )
                       AND s.managed_clients_raw > s.clientes_asignados                          THEN s.clientes_asignados                      ELSE s.managed_clients_raw                  END              ) AS clientes_gestionados,                CONVERT(                  INT,                  s.clientes_asignados                  - CASE                      WHEN
                        (
                            @historico_limitar_gestionados_a_asignados = 1
                            OR @normalizar_desfase_transitorio = 1
                        )
                       AND s.managed_clients_raw > s.clientes_asignados                          THEN s.clientes_asignados                      ELSE s.managed_clients_raw                    END              ) AS clientes_pendientes            INTO #EvolutionSource            FROM #ManagedNormalized AS s            INNER JOIN analitica.dim_cartera AS p              ON p.clave_cliente = @client_key             AND p.id_cartera_origen = s.nid_cartera             AND p.unidad_negocio_origen = @business_unit_name;              /* --------------------------------------------------------             8.3 UPDATE             -------------------------------------------------------- */            UPDATE f          SET              f.clientes_asignados =                  s.clientes_asignados,                f.clientes_gestionados =                  s.clientes_gestionados,                f.clientes_pendientes =                  s.clientes_pendientes,                f.fecha_corte_origen =                  @source_as_of_at,                f.fecha_carga =                  SYSUTCDATETIME()            FROM analitica.hecho_evolucion_cartera_diario AS f            INNER JOIN #EvolutionSource AS s              ON s.clave_fecha = f.clave_fecha             AND s.clave_cartera = f.clave_cartera            WHERE f.clave_cliente = @client_key            AND f.clave_campana = @campaign_key;              /* --------------------------------------------------------             8.4 INSERT             -------------------------------------------------------- */            INSERT INTO analitica.hecho_evolucion_cartera_diario          (              clave_fecha,              clave_cliente,              clave_campana,              clave_cartera,                clientes_asignados,              clientes_gestionados,              clientes_pendientes,                fecha_corte_origen          )            SELECT              s.clave_fecha,              @client_key,              @campaign_key,              s.clave_cartera,                s.clientes_asignados,              s.clientes_gestionados,              s.clientes_pendientes,                @source_as_of_at            FROM #EvolutionSource AS s            WHERE NOT EXISTS          (              SELECT 1                FROM analitica.hecho_evolucion_cartera_diario AS f                WHERE f.clave_fecha = s.clave_fecha                AND f.clave_cliente = @client_key                AND f.clave_campana = @campaign_key                AND f.clave_cartera = s.clave_cartera          );              /* --------------------------------------------------------             8.5 FULL MONTH REPROCESS               Todo lo que ya no exista en el universo canonical EVOL             de este mes se elimina del fact evolution.               No afecta Live/Snapshot porque viven en otras facts.             -------------------------------------------------------- */            DELETE f            FROM analitica.hecho_evolucion_cartera_diario AS f            WHERE f.clave_cliente = @client_key            AND f.clave_campana = @campaign_key              AND EXISTS            (                SELECT 1                FROM analitica.dim_cartera AS p                WHERE p.clave_cartera = f.clave_cartera                  AND p.clave_cliente = @client_key                  AND p.unidad_negocio_origen = @business_unit_name            )              AND NOT EXISTS            (                SELECT 1                  FROM #EvolutionSource AS s                  WHERE s.clave_fecha = f.clave_fecha                  AND s.clave_cartera = f.clave_cartera            );              /* --------------------------------------------------------             8.6 Watermark             -------------------------------------------------------- */            UPDATE integracion_datos_analitica.control_carga          SET              fecha_ultimo_exito =                  SYSUTCDATETIME(),                fecha_hora_ultimo_origen =                  @source_as_of_at,                id_ultimo_origen =                  NULL,                dias_solapamiento =                  0,                fecha_actualizacion =                  SYSUTCDATETIME()            WHERE codigo_origen = @watermark_source_code;              IF @@ROWCOUNT = 0          BEGIN                INSERT INTO integracion_datos_analitica.control_carga              (                  codigo_origen,                  fecha_ultimo_exito,                  fecha_hora_ultimo_origen,                  dias_solapamiento              )                VALUES              (                  @watermark_source_code,                  SYSUTCDATETIME(),                  @source_as_of_at,                  0              );            END;              COMMIT TRANSACTION;              /* ========================================================             9. RESUMEN             ======================================================== */            SELECT              @codigo_campana AS codigo_campana,                @codigo_unidad_negocio AS codigo_unidad_negocio,                @business_unit_name AS unidad_negocio_origen,                @source_as_of_at AS fecha_corte_origen,                /*                 Filas físicas DEL MES.                   Ya no incluye filas de agosto aunque su CampAval                 todavía sea C-07.              */              @source_rows AS source_rows,                COUNT(*) AS evolution_rows,                COUNT(                  DISTINCT f.clave_fecha              ) AS evolution_days,                COUNT(                  DISTINCT f.clave_cartera              ) AS portfolios,                MIN(                  d.fecha_calendario              ) AS first_evolution_date,                MAX(                  d.fecha_calendario              ) AS last_evolution_date,                'CLARO_EVOLUTION_DAILY_OK'                  AS assessment            FROM analitica.hecho_evolucion_cartera_diario AS f            INNER JOIN analitica.dim_fecha AS d              ON d.clave_fecha = f.clave_fecha            WHERE f.clave_cliente = @client_key            AND f.clave_campana = @campaign_key              AND EXISTS              (                  SELECT 1                  FROM analitica.dim_cartera AS p                  WHERE p.clave_cartera = f.clave_cartera                    AND p.clave_cliente = @client_key                    AND p.unidad_negocio_origen = @business_unit_name              );          END TRY        BEGIN CATCH            IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION;            THROW;        END CATCH;    END;
GO
